+/** infomodel_elements.c
+ *  Implements operations for Infomodel datatypes
+ *
+ * Wireshark - Network traffic analyzer
+ * By Gerald Combs <gerald@wireshark.org>
+ * Copyright 1998 Gerald Combs
+ *
+ * OPC UA PubSub UADP Dissector
+ * Author: Leon Schmidt <leon.schmidt@codewerk.de>
+ * Copyright (C) 2022 Codewerk GmbH
+ *
+ * SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#include <stdio.h>
+
+#include <wireshark.h>
+#include <epan/packet.h>
+
+#include "infomodel_elements.h"
+
+int Datatype_cmp(Datatype a, Datatype b) {
+    if (a.ns != b.ns) return b.ns - a.ns;
+    if (a.idType != b.idType) return b.idType - a.idType;
+    switch (a.idType)
+    {
+    case DATATYPEID_NUMERIC:
+        return b.id_num - a.id_num;
+    case DATATYPEID_STRING:
+        return g_ascii_strcasecmp(a.id_str, b.id_str);
+        /* TODO handle other id types */
+        /* case DATATYPEID_GUID: */
+        /* case DATATYPEID_OPAQUE: */
+    default:
+        return 0;
+    }
+}
+
+void Datatype_print(Datatype *self) {
+    if (self->idType == DATATYPEID_EMPTY) {
+        printf("empty");
+        return;
+    }
+    printf("ns=%d, ", self->ns);
+    switch (self->idType)
+    {
+    case DATATYPEID_NUMERIC:
+        printf("i=%d", self->id_num);
+        break;
+    case DATATYPEID_STRING:
+        printf("s=%s", self->id_str);
+    default:
+        break;
+    }
+}
+
+AliasMap *AliasMap_new(void) {
+    AliasMap *self = g_slice_new0(AliasMap);
+    return self;
+}
+
+void AliasMap_delete(AliasMap *self) {
+    if (!self) return;
+    AliasMap *tmp, *cur;
+    cur = self;
+    while (cur) {
+        tmp = cur;
+        cur = cur->next;
+        g_free(tmp->name);
+        if (tmp->type.idType == DATATYPEID_STRING) g_free(tmp->type.id_str);
+        g_slice_free(AliasMap, tmp);
+    }
+}
+
+void AliasMap_print(AliasMap *self) {
+    printf("%s: ", self->name);
+    Datatype_print(&self->type);
+    printf("\n");
+}
+
+int AliasMap_cmp(AliasMap *self, AliasMap *other) {
+    if (!self && !other) return 0;
+    else if (self && !other) return 1;
+    else if (!self && other) return -1;
+
+    int result;
+    result = g_ascii_strcasecmp(self->name, other->name);
+    if (result != 0) return result;
+    result = Datatype_cmp(self->type, other->type);
+    if (result != 0) return result;
+    result = self->aType - other->aType;
+    if (result != 0) return result;
+
+    return AliasMap_cmp(self->next, other->next);
+}
+
+/* Fill in type field depending on current name */
+void AliasMap_type_lookup(AliasMap *self) {
+    if      (!g_ascii_strcasecmp(self->name, "boolean"      )) self->aType = ALIAS_BOOLEAN;
+    else if (!g_ascii_strcasecmp(self->name, "sbyte"        )) self->aType = ALIAS_SBYTE;
+    else if (!g_ascii_strcasecmp(self->name, "byte"         )) self->aType = ALIAS_BYTE;
+    else if (!g_ascii_strcasecmp(self->name, "int16"        )) self->aType = ALIAS_INT16;
+    else if (!g_ascii_strcasecmp(self->name, "uint16"       )) self->aType = ALIAS_UINT16;
+    else if (!g_ascii_strcasecmp(self->name, "int32"        )) self->aType = ALIAS_INT32;
+    else if (!g_ascii_strcasecmp(self->name, "uint32"       )) self->aType = ALIAS_UINT32;
+    else if (!g_ascii_strcasecmp(self->name, "int64"        )) self->aType = ALIAS_INT64;
+    else if (!g_ascii_strcasecmp(self->name, "uint64"       )) self->aType = ALIAS_UINT64;
+    else if (!g_ascii_strcasecmp(self->name, "float"        )) self->aType = ALIAS_FLOAT;
+    else if (!g_ascii_strcasecmp(self->name, "double"       )) self->aType = ALIAS_DOUBLE;
+    else if (!g_ascii_strcasecmp(self->name, "datetime"     )) self->aType = ALIAS_DATETIME;
+    else if (!g_ascii_strcasecmp(self->name, "utctime"      )) self->aType = ALIAS_UTCTIME;
+    else if (!g_ascii_strcasecmp(self->name, "string"       )) self->aType = ALIAS_STRING;
+    else if (!g_ascii_strcasecmp(self->name, "bytestring"   )) self->aType = ALIAS_BYTESTRING;
+    else if (!g_ascii_strcasecmp(self->name, "localizedtext")) self->aType = ALIAS_LOCALIZEDTEXT;
+    else self->aType = ALIAS_INVALID;
+}
+
+Datatype AliasMap_find_name(AliasMap *self, const char *name) {
+    AliasMap *cur;
+    for (cur = self; cur; cur = cur->next) {
+        if (!g_ascii_strcasecmp(name, cur->name)) {
+            return cur->type;
+        }
+    }
+    Datatype default_ret;
+    memset(&default_ret, 0, sizeof(Datatype));
+    return default_ret;
+}
+
+Field *Field_new(void) {
+    Field *self = g_slice_new0(Field);
+    self->hf_id = -1;
+    self->ett_id = -1;
+    return self;
+}
+
+void Field_delete(Field *self, int proto_id) {
+    if (!self) return;
+    Field *tmp, *cur;
+    cur = self;
+    while (cur) {
+        tmp = cur;
+        cur = cur->next;
+        g_free(tmp->name);
+        if (tmp->type.idType == DATATYPEID_STRING) g_free(tmp->type.id_str);
+        /* TODO clean this up, destroy-notifier or something */
+        proto_deregister_field(proto_id, tmp->hf_id);
+        /* TODO ett cleanup, not really possible atm */
+        g_slice_free(Field, tmp);
+    }
+}
+
+void Field_print(Field *self, bool valueField) {
+    printf("\t%s: ", self->name);
+    if (valueField) {
+        printf("value=%d\n", self->value);
+    }
+    else {
+        Datatype_print(&self->type);
+        if (self->isArray) printf(" (Array)");
+        if (self->isOptional) printf(" (Optional)");
+        printf("\n");
+    }
+}
+
+int Field_cmp(Field *self, Field *other) {
+    if (!self && !other) return 0;
+    else if (self && !other) return 1;
+    else if (!self && other) return -1;
+
+    int result;
+    result = g_ascii_strcasecmp(self->name, other->name);
+    if (result != 0) return result;
+    result = Datatype_cmp(self->type, other->type);
+    if (result != 0) return result;
+    result = self->isArray - other->isArray;
+    if (result != 0) return result;
+
+    /* do not compare hf and ett ids! */
+    /* cmp should focus on infomodel logic, not wireshark metadata */
+
+    return Field_cmp(self->next, other->next);
+}
+
+AliasType Field_find_atype(Field *self, AliasMap *map) {
+    AliasMap *cur;
+    for (cur = map; cur; cur = cur->next) {
+        if (!Datatype_cmp(self->type, cur->type)) return cur->aType;
+    }
+    return ALIAS_INVALID;
+}
+
+CustomDatatype *Field_find_ctype(Field *self, CustomDatatype *ctype) {
+    CustomDatatype *cur;
+    for (cur = ctype; cur; cur = cur->next) {
+        if (!Datatype_cmp(self->type, cur->id)) return cur;
+    }
+    return NULL;
+}
+
+CustomDatatype *CustomDatatype_new(void) {
+    CustomDatatype *self = g_slice_new0(CustomDatatype);
+    self->ett_id = -1;
+    return self;
+}
+
+void CustomDatatype_delete(CustomDatatype *self, int proto_id) {
+    if (!self) return;
+    CustomDatatype *tmp, *cur;
+    cur = self;
+    while (cur) {
+        tmp = cur;
+        cur = cur->next;
+        Field_delete(tmp->fields_first, proto_id);
+        g_free(tmp->name);
+        if (tmp->id.idType == DATATYPEID_STRING) g_free(tmp->id.id_str);
+        g_slice_free(CustomDatatype, tmp);
+    }
+}
+
+void CustomDatatype_print(CustomDatatype *self) {
+    printf("Datatype: %s; Id: ", self->name);
+    Datatype_print(&self->id);
+    printf(" (");
+    switch (self->subtype)
+    {
+        /* TODO extend (maybe auto-generate?) */
+    case SUBTYPE_BOOLEAN:    printf("Boolean"); break;
+    case SUBTYPE_SBYTE:      printf("SByte"); break;
+    case SUBTYPE_BYTE:       printf("Byte"); break;
+    case SUBTYPE_INT16:      printf("Int16"); break;
+    case SUBTYPE_UINT16:     printf("UInt16"); break;
+    case SUBTYPE_INT32:      printf("Int32"); break;
+    case SUBTYPE_UINT32:     printf("UInt32"); break;
+    case SUBTYPE_INT64:      printf("Int64"); break;
+    case SUBTYPE_UINT64:     printf("UInt64"); break;
+    case SUBTYPE_FLOAT:      printf("Float"); break;
+    case SUBTYPE_DOUBLE:     printf("Double"); break;
+    case SUBTYPE_DATETIME:   printf("DateTime"); break;
+    case SUBTYPE_STRING:     printf("String"); break;
+    case SUBTYPE_BYTESTRING: printf("ByteString"); break;
+    case SUBTYPE_STRUCT:     printf("Structure"); break;
+    case SUBTYPE_ENUM:       printf("Enumeration"); break;
+    case SUBTYPE_OPTIONSET:  printf("OptionSet"); break;
+    case SUBTYPE_CUSTOM:     printf("%s", self->customSubtype->name); break;
+    default:                 printf("Unknown Subtype"); break;
+    }
+    printf(")");
+    /* if (self->hasOptionalFields) printf(" (Optional Fields)"); */
+    printf("\n");
+    Field *cur;
+    for (cur = self->fields_first; cur; cur = cur->next) {
+        Field_print(cur, self->subtype != SUBTYPE_STRUCT);
+    }
+}
+
+int CustomDatatype_cmp(CustomDatatype *self, CustomDatatype *other) {
+    if (!self && !other) return 0;
+    else if (self && !other) return 1;
+    else if (!self && other) return -1;
+
+    int result;
+    result = g_ascii_strcasecmp(self->name, other->name);
+    if (result != 0) return result;
+    result = Datatype_cmp(self->id, other->id);
+    if (result != 0) return result;
+
+    return CustomDatatype_cmp(self->next, other->next);
+}
+
+void CustomDatatype_add_field(CustomDatatype *self, Field *field) {
+    if (self->fields_last) {
+        self->fields_last->next = field;
+    }
+    else {
+        self->fields_first = field;
+    }
+    self->fields_last = field;
+}
+
+CustomDatatype *CustomDatatype_find(CustomDatatype *self, Datatype nodeId) {
+    CustomDatatype *cur;
+    for (cur = self; cur; cur = cur->next) {
+        if (!Datatype_cmp(cur->id, nodeId)) return cur;
+    }
+    return NULL;
+}
+
+UAObject *UAObject_new(void) {
+    UAObject *self = g_slice_new0(UAObject);
+    return self;
+}
+
+void UAObject_delete(UAObject *self) {
+    if (!self) return;
+    UAObject *tmp, *cur;
+    cur = self;
+    while (cur) {
+        tmp = cur;
+        cur = cur->next;
+        g_free(tmp->name);
+        if (tmp->id.idType == DATATYPEID_STRING) g_free(tmp->id.id_str);
+        if (tmp->refEncodingRaw.idType == DATATYPEID_STRING) g_free(tmp->refEncodingRaw.id_str);
+        g_slice_free(UAObject, tmp);
+    }
+}
+
+void UAObject_print(UAObject *self) {
+    printf("UA Object: %s; Id: ", self->name);
+    Datatype_print(&self->id);
+    if (self->refEncodingRaw.idType != DATATYPEID_EMPTY) {
+        printf("; Encoding: ");
+        Datatype_print(&self->refEncodingRaw);
+    }
+    printf("\n");
+}
+
+int UAObject_cmp(UAObject *self, UAObject *other) {
+    if (!self && !other) return 0;
+    else if (self && !other) return 1;
+    else if (!self && other) return -1;
+
+    int result;
+    result = g_ascii_strcasecmp(self->name, other->name);
+    if (result != 0) return result;
+    result = Datatype_cmp(self->id, other->id);
+    if (result != 0) return result;
+    result = Datatype_cmp(self->refEncodingRaw, other->refEncodingRaw);
+    if (result != 0) return result;
+
+    return UAObject_cmp(self->next, other->next);
+}
+
+Infomodel *Infomodel_new(void) {
+    Infomodel *self = g_slice_new0(Infomodel);
+    return self;
+}
+
+void Infomodel_delete(Infomodel *self, int proto_id) {
+    if (!self) return;
+    AliasMap_delete(self->aliases_first);
+    CustomDatatype_delete(self->customDatatype_first, proto_id);
+    UAObject_delete(self->objects_first);
+    if (self->dissected_type.idType == DATATYPEID_STRING) g_free(self->dissected_type.id_str);
+    g_slice_free(Infomodel, self);
+}
+
+void Infomodel_print(Infomodel *self) {
+    printf("AliasMap\n==========\n");
+    AliasMap *cur_map;
+    for (cur_map = self->aliases_first; cur_map; cur_map = cur_map->next) {
+        AliasMap_print(cur_map);
+    }
+
+    printf("\nCustom Datatypes\n==============\n");
+    CustomDatatype *cur_type;
+    for (cur_type = self->customDatatype_first; cur_type; cur_type = cur_type->next) {
+        CustomDatatype_print(cur_type);
+    }
+
+    printf("\nUA Objects\n==============\n");
+    UAObject *cur_obj;
+    for (cur_obj = self->objects_first; cur_obj; cur_obj = cur_obj->next) {
+        UAObject_print(cur_obj);
+    }
+
+    if (self->ns_offset) printf("\nNS offset: %d\n\n", *(self->ns_offset));
+
+    printf("Dissected type: ");
+    Datatype_print(&self->dissected_type);
+    printf("\n");
+}
+
+void Infomodel_add_aliasmap_entry(Infomodel *self, AliasMap *map) {
+    if (self->aliases_last) {
+        self->aliases_last->next = map;
+    }
+    else {
+        self->aliases_first = map;
+    }
+    self->aliases_last = map;
+}
+
+void Infomodel_add_type(Infomodel *self, CustomDatatype *cType) {
+    if (self->customDatatype_last) {
+        self->customDatatype_last->next = cType;
+    }
+    else {
+        self->customDatatype_first = cType;
+    }
+    self->customDatatype_last = cType;
+}
+
+void Infomodel_add_object(Infomodel *self, UAObject *object) {
+    if (self->objects_last) {
+        self->objects_last->next = object;
+    }
+    else {
+        self->objects_first = object;
+    }
+    self->objects_last = object;
+}
+
+int Infomodel_cmp(Infomodel *self, Infomodel *other) {
+    if (!self && !other) return 0;
+    else if (self && !other) return 1;
+    else if (!self && other) return -1;
+
+    int result;
+    result = AliasMap_cmp(self->aliases_first, other->aliases_first);
+    if (result != 0) return result;
+    result = CustomDatatype_cmp(self->customDatatype_first, other->customDatatype_first);
+    if (result != 0) return result;
+    result = UAObject_cmp(self->objects_first, other->objects_first);
+    /* if (result != 0) */ return result;
+
+    /*
+    if (self->ns_offset && other->ns_offset) {
+        result = *(self->ns_offset) - *(other->ns_offset);
+        if (result != 0) return result;
+    }
+    else if (self->ns_offset) return 1;
+    else if (other->ns_offset) return -1;
+
+    result = Datatype_cmp(self->dissected_type, other->dissected_type);
+    */
+}

